import{z as o,x as s,o as r,c,q as n,j as i,D as e,d as E,s as A,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"跨资产配置的战术层","description":"","frontmatter":{"title":"跨资产配置的战术层","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-tactical-allocation.md","filePath":"quant/mac-tactical-allocation.md","lastUpdated":1791413859000}'),d={name:"quant/mac-tactical-allocation.md"};function p(h,a,m,u,D,f){const B=s("Mermaid");return r(),c("div",null,[a[2]||(a[2]=n('<h1 id="跨资产配置的战术层" tabindex="-1">跨资产配置的战术层 <a class="header-anchor" href="#跨资产配置的战术层" aria-label="Permalink to &quot;跨资产配置的战术层&quot;">​</a></h1><div class="epigraph"><p>政策组合决定回报的大头；战术层花钱买的不是更高收益，而是围绕参考组合的偏离权——偏离有界，错了才付得起。</p><footer>—— 据 Brinson, Hood &amp; Beebower, Financial Analysts Journal, 1986 与 Sharpe, Financial Analysts Journal, 2010 整理</footer></div><p><a href="/quant/mac-liquidity-conditions">上一课</a>把流动性提成第三根轴，并留下一条执行纪律：换仓的最差时点恰恰是条件指数报紧的时点。至此框架课的三件工具齐了——状态概率、象限映射表、风险开关；本课把它们收进同一个执行框架：围绕政策组合的战术偏离层。第二课映射表里标注的「战术偏离」在这里落地，后面的利率、外汇、商品三课，都在这一层里各占一个表达账户。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>战术配置的常见死法不是判断错，而是没有结构：状态概率、象限表、carry、动量各自成单，账户上只剩一组没人批准过的总偏离——跟踪误差无预算，信号互相抵消却各付一遍成本，同向时风险翻倍。缺口是把「多个信号」合成「一组仓位偏离」，并且回答四个问题：偏离相对谁定义？幅度多大？何时进退、成本谁付？盈亏记在谁头上？不给答案，前三课的概率与映射就只是报告素材。</p><p><span class="marginnote">「跟踪误差（TE）」翻译成白话：你的组合与参考组合收益之差的波动率，衡量「偏离得有多野」。TE 预算就是给自己定的「最多能偏多远」——例如年化 TE 上限 2%，意味着正常年份战术偏离带来的盈亏大多落在参考收益 ±2% 之内。</span></p><h3 id="围绕参考组合的偏离结构" tabindex="-1">围绕参考组合的偏离结构 <a class="header-anchor" href="#围绕参考组合的偏离结构" aria-label="Permalink to &quot;围绕参考组合的偏离结构&quot;">​</a></h3><p>政策组合先立住：它承载战略风险预算，是战术的参考点。战术写成偏离 \\(\\Delta w_t\\)，预算用跟踪误差带住，偏离的协方差用收缩后的 \\(\\Sigma\\) 估出（<a href="/quant/cov-shrinkage">协方差收缩</a>）；锚可选等风险贡献（<a href="/quant/risk-parity">风险平价</a>）或市场均衡（<a href="/quant/black-litterman">Black–Litterman</a>）。每个信号先折成方向与强度的标量：状态概率给置信度（第一课），象限格给相对赢家（第二课），carry 与动量给截面排序（<a href="/quant/carry-everywhere">Carry</a>、<a href="/quant/cta-tsmom">时序动量</a>），流动性开关只许压不许放（第三课）。</p><p><span class="marginnote">Brinson 等的样本里，政策权重解释了 91 支养老基金总收益方差的约 93.6%。把「择时贡献」算成收益占比而不是方差占比，是战术层价值最常被夸大的口径错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地四步。第一步定预算：总跟踪误差上限先于任何信号存在，满偏离对应的主动风险不得超过它。第二步合成信号：各信号标准化成 \\([-1,1]\\) 的强度，按风险预算等权加权，而不是按样本内夏普加权——后者把多重检验直接搬进仓位。第三步定尺寸：偏离 \\(=\\) 满偏 \\(\\times\\) 强度，满偏由 TE 预算反解；状态概率贴着阈值抖动时按概率带渐进调仓，与第一课同口径。第四步执行：再平衡带宽住微调，换格与翻仓按上一课拆片、预扣冲击成本；并与既有的 CTA 或<a href="/quant/vol-targeting">波动目标</a>模块对表，防止同一信号在两个账户里双计。</p><p><span class="marginnote">数字示例：设满偏为股票超配 4%、某月合成信号强度 0.5，则实际偏离就是超配 2%。强度按概率带渐进——概率从 0.6 涨到 0.8，强度从 0.5 升到 0.75，偏离跟着爬向 3%，而不是一步跳满 4%。</span></p>',12)),(r(),i(l,null,{default:e(()=>[A(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%94%BF%E7%AD%96%E7%BB%84%E5%90%88%EF%BC%88%E5%8F%82%E8%80%83%E7%82%B9%EF%BC%89%22%5D%20--%3E%20B%5B%22%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%22%5D%0A%20%20P1%5B%22%E7%8A%B6%E6%80%81%E6%A6%82%E7%8E%87%22%5D%20--%3E%20C%5B%22%E4%BF%A1%E5%8F%B7%E5%90%88%E6%88%90%22%5D%0A%20%20P2%5B%22%E8%B1%A1%E9%99%90%E8%B5%A2%E5%AE%B6%22%5D%20--%3E%20C%0A%20%20P3%5B%22carry%20%E4%B8%8E%E5%8A%A8%E9%87%8F%22%5D%20--%3E%20C%0A%20%20P4%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E5%BC%80%E5%85%B3%22%5D%20--%3E%20C%0A%20%20B%20--%3E%20D%5B%22%E5%81%8F%E7%A6%BB%E5%AE%9A%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22%E5%86%8D%E5%B9%B3%E8%A1%A1%E5%B8%A6%E4%B8%8E%E6%8B%86%E7%89%87%E6%89%A7%E8%A1%8C%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%8C%89%E5%81%8F%E7%A6%BB%E5%BD%92%E5%9B%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("为什么围绕参考组合而不是整体推倒重排：主动风险是稀缺品，TE 预算应集中在最可证伪的信号上；参考组合保证任何时刻账户的风险结构可解释，偏离的盈亏能单独归因——「政策赚的」与「战术赚的」混记，战术层就永远无法被验收，也无法被关停。信号合成的机制意义在相关性：carry、动量与象限映射在危机里常常同向（"),t("a",{href:"/quant/crisis-alpha"},"危机 alpha"),E(" 的凸性正来自趋势翻空），有效偏离数远小于信号个数，按信号个数平分预算会隐性放大总风险。流动性开关只压不放的理由也在此：它判断的是执行条件不是收益方向，funding 紧时唯一正确的动作是收缩。")],-1)),(r(),i(l,null,{default:e(()=>[A(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E8%B1%A1%E9%99%90%E6%98%A0%E5%B0%84%22%5D%20--%3E%20W%5B%22%E6%AD%A3%E5%B8%B8%E6%97%B6%E6%9C%9F%3A%20%E4%BF%A1%E5%8F%B7%E7%9B%B8%E5%85%B3%E4%BD%8E%22%5D%0A%20%20S2%5B%22carry%22%5D%20--%3E%20W%0A%20%20S3%5B%22%E5%8A%A8%E9%87%8F%22%5D%20--%3E%20W%0A%20%20W%20--%3E%20OK%5B%22%E5%81%8F%E7%A6%BB%E5%88%86%E6%95%A3%2C%20%E6%80%BB%E9%A3%8E%E9%99%A9%E5%8F%AF%E6%8E%A7%22%5D%0A%20%20CRS%5B%22%E5%8D%B1%E6%9C%BA%E6%9D%A5%E4%B8%B4%22%5D%20--%3E%20C1%5B%22%E5%A4%9A%E8%B7%AF%E4%BF%A1%E5%8F%B7%E5%90%8C%E6%97%B6%E7%BF%BB%E7%A9%BA%22%5D%0A%20%20C1%20--%3E%20SAME%5B%22%E5%81%8F%E7%A6%BB%E8%81%9A%E5%88%B0%E5%90%8C%E4%B8%80%E6%96%B9%E5%90%91%22%5D%0A%20%20SAME%20--%3E%20BAD%5B%22%E6%9C%89%E6%95%88%E5%81%8F%E7%A6%BB%E6%95%B0%E9%AA%A4%E9%99%8D%22%5D%0A%20%20CAP%5B%22%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%E4%B8%8A%E9%99%90%22%5D%20--%3E%20CUT%5B%22%E4%BA%8B%E5%89%8D%E6%8C%89%E9%A2%84%E7%AE%97%E5%8E%8B%E6%9D%83%E9%87%8D%22%5D%0A%20%20BAD%20--%3E%20CUT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">为什么重要：若「政策赚的」与「战术赚的」混在一本账里，战术层赚了不知该不该奖、亏了不知该不该罚，最后变成没人能证明价值、也没人敢关停的黑箱。偏离单独记账，是战术层唯一能被验收的方式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>战术层修不了政策错误：政策组合的贝塔本身摆错位置，战术是在错误地基上做微雕；Brinson 的方差分解既是战术层的价值上限，也是它的免责条款——偏离预算不保证战术为正，只保证它错时的损失有界。信号频率错配要显式处理：象限以季计、动量以月计、流动性以日计，放进同一个合成器之前先分层，否则最快的信号实际上决定了全部仓位。也不神化参考组合：政策再平衡与战术换仓共用同一本成本账，口径必须一致，否则归因第一层就失真。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>战术层是围绕政策组合的有界偏离：跟踪误差预算先行，信号只决定预算怎么花。</li><li>信号各折成方向与强度后按风险预算合成；概率带渐进，流动性开关只压不放。</li><li>危机里多信号同向，有效偏离数远小于信号个数；按信号数分预算会放大风险。</li><li>偏离单独记账与归因，战术层才能被验收、被关停。</li><li>出处：Brinson, Hood &amp; Beebower, FAJ, 1986；Sharpe, FAJ, 2010；锚与协方差构造见<a href="/quant/cov-shrinkage">协方差收缩</a>、<a href="/quant/risk-parity">风险平价</a>与<a href="/quant/black-litterman">Black–Litterman</a>。</li></ul>',5))])}const q=o(d,[["render",p]]);export{C as __pageData,q as default};
